#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);
    vector<pair<int,int>> ops;
    auto apply=[&](int x,int y){
        ops.push_back({x,y});
        vector<int> q(n);
        for(int i=0;i<y;i++) q[i]=p[n-y+i];
        for(int i=0;i<n-x-y;i++) q[y+i]=p[x+i];
        for(int i=0;i<x;i++) q[n-x+i]=p[i];
        p=q;
    };
    auto pos_of=[&](int v)->int{for(int i=0;i<n;i++) if(p[i]==v) return i; return -1;};

    for(int t=0;t<n;t++){
        int pos=pos_of(t+1);
        if(pos==t) continue;
        // We work in the subarray [t..n-1] conceptually, but operations are global.
        // Move element to position t.
        // Step 1: move to position 0 if not there
        if(pos>0){
            if(pos>=2){
                apply(1, n-pos); // suffix=[pos..n-1], mid=[1..pos-1], prefix=[0]
                // element was at pos, now at position 0
            } else {
                // pos==1
                if(n>=3){
                    apply(2, n-2); // suffix=[2..n-1], mid=[nothing if 2+n-2=n], prefix=[0,1]
                    // Actually mid size = n-2-(n-2)=0. So result: [p[2]..p[n-1]] [p[0] p[1]]
                    // element at pos=1 goes to position n-1
                    // Then move from n-1 to 0
                    apply(1, 1); // suffix=[n-1], mid=[1..n-2], prefix=[0] -> element at 0
                }
            }
        }
        pos=pos_of(t+1);
        if(pos==0 && t>0){
            // Move from 0 to t
            int rem=n-t; // elements in [t..n-1]
            if(t>=1 && n-1-t>=1 && t+(n-1-t)<=n-1){
                apply(t, n-1-t);
                // suffix=[t+1..n-1], mid=[t..t], prefix=[0..t-1] -> elem at n-t
            }
            pos=pos_of(t+1);
            if(pos!=t && pos>0){
                if(pos>=2) apply(1,n-pos);
                else if(n>=3) { apply(2,n-2); apply(1,1); }
                pos=pos_of(t+1);
                if(pos==0&&t>0){ apply(t,n-1-t); pos=pos_of(t+1);}
            }
        }
    }
    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
